// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.TenantEvidenceKey) predicate.TenantEvidenceKey {
	return predicate.TenantEvidenceKey(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.TenantEvidenceKey) predicate.TenantEvidenceKey {
	return predicate.TenantEvidenceKey(sql.NotPredicates(p))
}
